[hidden] { display: none !important; }
:root { color-scheme: light; --ink: #20283a; --muted: #687287; --paper: #fffdf8; --line: #e8e5dc; --blue: #4967e8; --pink: #f29c9b; --mint: #bdebd9; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 28px 16px; color: var(--ink); background-color: #f7c5a8; background-image: radial-gradient(circle at 12% 20%, #ffe4a8 0 7%, transparent 7.2%), radial-gradient(circle at 88% 78%, #bdebd9 0 10%, transparent 10.2%), linear-gradient(145deg, #f7c5a8, #f6d2bf 52%, #eec3da); font: 16px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif; }
.card { width: min(100%, 480px); padding: 36px 38px 24px; background: var(--paper); border: 3px solid var(--ink); border-radius: 18px; box-shadow: 8px 8px 0 var(--ink); }
.heading { text-align: center; }
.eyebrow { color: var(--blue); font-size: 14px; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 8px 0 2px; font-size: clamp(30px, 8vw, 38px); line-height: 1.15; letter-spacing: -.04em; }
.heading p, .step-hint { margin: 0; color: var(--muted); }
.progress-wrap { margin: 28px 0 30px; }
.progress-label { display: flex; justify-content: space-between; gap: 12px; font-size: 14px; font-weight: 700; }
.progress-label span:last-child { color: var(--muted); }
.progress-track { height: 10px; margin-top: 9px; overflow: hidden; border: 2px solid var(--ink); border-radius: 8px; background: #f1eee7; }
#progress-fill { display: block; width: 0; height: 100%; background: var(--blue); transition: width .25s ease; }
.step-dots { display: flex; justify-content: space-between; margin: 8px 0 0; padding: 0; list-style: none; color: var(--muted); font-size: 13px; }
.step-dots li.active { color: var(--blue); font-weight: 800; }
.step-panel h2 { margin: 0; font-size: 22px; }
.step-hint { margin: 2px 0 20px; }
form label:not(.plan-option) { display: block; margin: 14px 0 6px; font-weight: 700; }
input[type="text"], input[type="email"] { width: 100%; min-height: 48px; padding: 10px 12px; color: var(--ink); background: white; border: 2px solid #cfd3dc; border-radius: 9px; font: inherit; }
input::placeholder { color: #9299a7; }
input:focus-visible, button:focus-visible { outline: 3px solid #f29c9b; outline-offset: 3px; }
.plans { display: grid; gap: 10px; margin: 0; padding: 0; border: 0; }
.plan-option { display: flex; align-items: center; gap: 12px; min-height: 68px; padding: 11px 13px; border: 2px solid var(--line); border-radius: 10px; cursor: pointer; transition: border-color .15s, background .15s, transform .15s; }
.plan-option:hover { border-color: var(--blue); transform: translateY(-1px); }
.plan-option:has(input:checked) { border-color: var(--blue); background: #f0f2ff; }
.plan-option input { width: 19px; height: 19px; accent-color: var(--blue); }
.plan-copy { display: grid; flex: 1; }
.plan-copy small { color: var(--muted); font-size: 14px; }
.plan-price { font-weight: 800; }
.plan-price span { color: var(--muted); font-size: 13px; font-weight: 500; }
.summary { margin: 4px 0 0; border-top: 2px solid var(--line); }
.summary div { display: flex; justify-content: space-between; gap: 12px; padding: 13px 2px; border-bottom: 2px solid var(--line); }
.summary dt { color: var(--muted); }
.summary dd { max-width: 65%; margin: 0; overflow-wrap: anywhere; font-weight: 750; text-align: right; }
.form-error { min-height: 22px; margin: 7px 0 0; color: #b23542; font-size: 14px; }
.success { padding: 12px; color: #175b45; background: #e3f7ed; border-radius: 8px; font-weight: 700; }
.actions { display: flex; gap: 12px; margin-top: 19px; }
button { min-height: 48px; padding: 10px 16px; border: 2px solid var(--ink); border-radius: 9px; font: inherit; font-weight: 800; cursor: pointer; transition: transform .12s, box-shadow .12s, background .12s; }
button:hover:not(:disabled) { transform: translateY(-2px); box-shadow: 0 3px 0 var(--ink); }
button:active:not(:disabled) { transform: translateY(1px); box-shadow: none; }
.back-button { color: var(--ink); background: transparent; }
.next-button { flex: 1; color: white; background: var(--blue); }
.next-button:disabled { color: #7b8290; background: #e3e4e8; border-color: #c9cbd1; cursor: not-allowed; }
footer { margin-top: 22px; color: var(--muted); font-size: 13px; text-align: center; }
footer span { color: var(--blue); }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 420px) { .card { padding: 28px 22px 20px; box-shadow: 5px 5px 0 var(--ink); } .progress-wrap { margin: 23px 0 25px; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; } }

const form = document.querySelector('#signup-form');
const panels = [...document.querySelectorAll('.step-panel')];
const dots = [...document.querySelectorAll('.step-dots li')];
const nextButton = document.querySelector('#next-button');
const backButton = document.querySelector('#back-button');
const confirmButton = document.querySelector('#confirm-button');
const progress = document.querySelector('[role="progressbar"]');
const progressFill = document.querySelector('#progress-fill');
let step = 0;

function validCurrentStep() {
  if (step === 0) {
    const name = form.elements.name;
    const email = form.elements.email;
    const error = document.querySelector('#details-error');
    if (!name.value.trim() || name.value.trim().length < 2) error.textContent = 'Please enter a name with at least 2 characters.';
    else if (!email.validity.valid || !email.value.trim()) error.textContent = 'Please enter a valid email address.';
    else { error.textContent = ''; return true; }
    return false;
  }
  const selected = form.querySelector('input[name="plan"]:checked');
  document.querySelector('#plan-error').textContent = selected ? '' : 'Choose a plan to continue.';
  return Boolean(selected);
}

function update() {
  panels.forEach((panel, index) => { panel.hidden = index !== step; });
  dots.forEach((dot, index) => {
    dot.classList.toggle('active', index === step);
    if (index === step) dot.setAttribute('aria-current', 'step'); else dot.removeAttribute('aria-current');
  });
  document.querySelector('#step-label').textContent = `Step ${step + 1} of 3`;
  document.querySelector('#step-name').textContent = ['Your details', 'Choose a plan', 'Review'][step];
  progress.setAttribute('aria-valuenow', String(step + 1));
  progressFill.style.width = `${((step + 1) / 3) * 100}%`;
  backButton.hidden = step === 0;
  nextButton.hidden = step === 2;
  confirmButton.hidden = step !== 2;
  nextButton.disabled = !validCurrentStep();
  if (step === 2) {
    document.querySelector('#summary-name').textContent = form.elements.name.value.trim();
    document.querySelector('#summary-email').textContent = form.elements.email.value.trim();
    document.querySelector('#summary-plan').textContent = form.querySelector('input[name="plan"]:checked')?.value || '';
  }
}

form.addEventListener('input', () => { if (step < 2) update(); });
form.addEventListener('change', () => { if (step < 2) update(); });
nextButton.addEventListener('click', () => {
  if (!validCurrentStep()) { update(); return; }
  step += 1;
  update();
  panels[step].querySelector('h2').focus?.();
});
backButton.addEventListener('click', () => { step -= 1; update(); });
form.addEventListener('submit', event => {
  event.preventDefault();
  if (step !== 2) return;
  document.querySelector('#success-message').hidden = false;
  confirmButton.disabled = true;
  confirmButton.textContent = 'Confirmed ✓';
});
update();
